<div class="d-flex justify-content-between mb-4 gap-3"><form method="get" class="d-flex gap-2"><input id="admin-product-search" class="form-control" name="q" value="<?= e($q) ?>" placeholder="Tìm tên sản phẩm"><button class="btn btn-light" type="submit">Tìm</button></form><a href="/admin/products/create" class="btn btn-primary">+ Thêm sản phẩm</a></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Sản phẩm / SKU</th><th>Danh mục</th><th>Giá bán</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?= e($p['name']) ?></b><small class="d-block muted"><?= e($p['sku']) ?> · <?= e($p['brand_name']) ?></small></td><td><?= e($p['category_name']) ?></td><td><?= money($p['price']) ?></td><td><?= $p['stock'] ?></td><td><span class="status"><?= $p['is_active']?'Đang bán':'Ngừng bán' ?></span></td><td><div class="d-flex gap-2"><a class="btn btn-light btn-sm" href="/admin/products/<?= $p['id'] ?>/edit">Sửa</a><form action="/admin/products/<?= $p['id'] ?>/delete" method="post" data-confirm="Ngừng bán sản phẩm này?"><?= App\Core\Csrf::field() ?><button class="btn btn-light btn-sm" type="submit">Ngừng bán</button></form></div></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/pagination.php';?>
